{
  "name": "Picomotor 微位移电机控制器",
  "name_en": "Picomotor Controller",
  "manufacturer": "Newport",
  "description": "这是一种用于驱动和控制 Picomotor 微位移执行器的运动控制器，通常通过 USB 与计算机连接。它常用于实验室中的精密光学调整、镜架或平台的微小位移调节，以及需要高分辨率机械定位的场景。",
  "description_en": "This is a motion controller for driving and controlling Picomotor micro-positioning actuators, typically connected to a computer via USB. It is commonly used in laboratories for fine optical alignment, small displacement adjustment of mounts or stages, and other applications requiring high-resolution mechanical positioning.",
  "actions": [
    {
      "action_name": "auto-send_command",
      "description": "向控制器发送一条 USB 命令，可选读取返回数据。",
      "description_en": "Send a USB command to the controller, optionally reading back a reply."
    },
    {
      "action_name": "auto-parse_command",
      "description": "将 New Focus 风格命令解析并转换为控制器可接收的 USB 命令格式。",
      "description_en": "Parse a New Focus-style command and convert it into a USB command format accepted by the controller."
    },
    {
      "action_name": "auto-parse_reply",
      "description": "解析控制器返回的数据并转换为可读文本。",
      "description_en": "Parse the controller reply and convert it into human-readable text."
    },
    {
      "action_name": "auto-command",
      "description": "向控制器发送一条标准命令，并在查询命令时返回解析后的响应。",
      "description_en": "Send a standard command to the controller and return the parsed response for query commands."
    },
    {
      "action_name": "auto-start_console",
      "description": "启动交互式控制台，连续输入并发送控制器命令。",
      "description_en": "Start an interactive console for continuously entering and sending controller commands."
    }
  ],
  "tag_hints": [
    "picomotor positioning",
    "precision motion control",
    "optical alignment",
    "micro-positioning actuator",
    "USB motion controller",
    "multi-axis positioning"
  ]
}

